public class InnerOAuth2CredentialProviderCustomOauth2ProviderConfigInputFactory(Action<Humidifier.BedrockAgentCore.OAuth2CredentialProviderTypes.CustomOauth2ProviderConfigInput> factoryAction = null) : SubResourceFactory<Humidifier.BedrockAgentCore.OAuth2CredentialProviderTypes.CustomOauth2ProviderConfigInput>
{

    internal InnerOAuth2CredentialProviderOnBehalfOfTokenExchangeConfigFactory OnBehalfOfTokenExchangeConfigFactory { get; set; }

    internal InnerOAuth2CredentialProviderSecretReferenceFactory ClientSecretConfigFactory { get; set; }

    internal InnerOAuth2CredentialProviderPrivateKeyJwtConfigFactory PrivateKeyJwtConfigFactory { get; set; }

    internal InnerOAuth2CredentialProviderPrivateEndpointFactory PrivateEndpointFactory { get; set; }

    internal InnerOAuth2CredentialProviderOauth2DiscoveryFactory OauthDiscoveryFactory { get; set; }

    protected override Humidifier.BedrockAgentCore.OAuth2CredentialProviderTypes.CustomOauth2ProviderConfigInput Create()
    {
        var customOauth2ProviderConfigInputResult = CreateCustomOauth2ProviderConfigInput();
        factoryAction?.Invoke(customOauth2ProviderConfigInputResult);

        return customOauth2ProviderConfigInputResult;
    }

    private Humidifier.BedrockAgentCore.OAuth2CredentialProviderTypes.CustomOauth2ProviderConfigInput CreateCustomOauth2ProviderConfigInput()
    {
        var customOauth2ProviderConfigInputResult = new Humidifier.BedrockAgentCore.OAuth2CredentialProviderTypes.CustomOauth2ProviderConfigInput();

        return customOauth2ProviderConfigInputResult;
    }
    public override void CreateChildren(Humidifier.BedrockAgentCore.OAuth2CredentialProviderTypes.CustomOauth2ProviderConfigInput result)
    {
        base.CreateChildren(result);

        result.OnBehalfOfTokenExchangeConfig ??= OnBehalfOfTokenExchangeConfigFactory?.Build();
        result.ClientSecretConfig ??= ClientSecretConfigFactory?.Build();
        result.PrivateKeyJwtConfig ??= PrivateKeyJwtConfigFactory?.Build();
        result.PrivateEndpoint ??= PrivateEndpointFactory?.Build();
        result.OauthDiscovery ??= OauthDiscoveryFactory?.Build();
    }

} // End Of Class

